module TopModule(
    input  clk,
    input  in,
    input  reset,
    output reg [7:0] out_byte,
    output reg done
);

    parameter IDLE  = 4'd0;
    parameter B0    = 4'd1;
    parameter B1    = 4'd2;
    parameter B2    = 4'd3;
    parameter B3    = 4'd4;
    parameter B4    = 4'd5;
    parameter B5    = 4'd6;
    parameter B6    = 4'd7;
    parameter B7    = 4'd8;
    parameter STOP  = 4'd9;
    parameter WAIT  = 4'd10;

    reg [3:0] state, next_state;

    always @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
            out_byte <= 8'b0;
            done <= 1'b0;
        end else begin
            state <= next_state;

            case (state)
                B0: out_byte[0] <= in;
                B1: out_byte[1] <= in;
                B2: out_byte[2] <= in;
                B3: out_byte[3] <= in;
                B4: out_byte[4] <= in;
                B5: out_byte[5] <= in;
                B6: out_byte[6] <= in;
                B7: out_byte[7] <= in;
                default: ;
            endcase

            if (state == STOP && in == 1'b1)
                done <= 1'b1;
            else
                done <= 1'b0;
        end
    end

    always @* begin
        next_state = state;
        case (state)
            IDLE: begin
                if (in == 1'b0)
                    next_state = B0;
                else
                    next_state = IDLE;
            end
            B0: next_state = B1;
            B1: next_state = B2;
            B2: next_state = B3;
            B3: next_state = B4;
            B4: next_state = B5;
            B5: next_state = B6;
            B6: next_state = B7;
            B7: next_state = STOP;
            STOP: begin
                if (in == 1'b1) begin
                    next_state = IDLE;
                end else begin
                    next_state = WAIT;
                end
            end
            WAIT: begin
                if (in == 1'b1)
                    next_state = IDLE;
                else
                    next_state = WAIT;
            end
            default: next_state = IDLE;
        endcase
    end

endmodule

